"""Offline audit board; private media embedded only when explicitly requested."""
from __future__ import annotations
import base64,html,json,mimetypes
from pathlib import Path
from urllib.parse import quote


def _img_uri(path):
    p=Path(path)
    mime=mimetypes.guess_type(p.name)[0] or 'image/png'
    if mime not in ('image/png','image/jpeg','image/webp'):raise ValueError('Unsupported visual asset')
    return 'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()


def stage_badge(status):
    cls={'PASS':'pass','PASS_SYNTHETIC_ONLY':'synthetic','BLOCKED':'blocked','NOT_TESTED':'held'}.get(status,'held')
    return f'<span class="badge {cls}">{html.escape(status.replace("_"," "))}</span>'


def render(report, out_path, *, sketch=None,photos=(),annotated=None,embed_private=False):
    """No external CDN, tracking, data transfer or model calls; no pretend 3D site map."""
    s=report['synthetic']; r=report['real']; lines=[]
    for item in report['stage_gate']:
        lines.append('<div class="step">'+stage_badge(item['status'])+
             f'<div><strong>{html.escape(item["name"])}</strong><small>{html.escape(item["evidence"])}</small></div></div>')
    thumbs=''
    if embed_private:
        if sketch:thumbs+=f'<figure class="sketch"><img src="{_img_uri(sketch)}"><figcaption>Original sketch — retained as source, not a measured plan</figcaption></figure>'
        if annotated:thumbs+=f'<figure class="sketch"><img src="{_img_uri(annotated)}"><figcaption>Four tentative ink groups — pixel boxes; inferred intent not established</figcaption></figure>'
        for i,p in enumerate(photos):
            thumbs+=f'<figure><img src="{_img_uri(p)}" loading="lazy"><figcaption>Photograph {i+1:02d}, independent camera frame; not georegistered</figcaption></figure>'
    else:
        thumbs='<p class="callout">Private photographs are intentionally not embedded in this public source audit.</p>'
    stages=''.join(lines)
    # JSON parsed as inert text node, not HTML. Replace dangerous close tags (future string evidence).
    payload=json.dumps({'first':s['first'],'second':s['second'],'observation':s['observation'],
                         'source':{'stroke_count':r['perception']['ink_groups'],
                                   'images':r['perception']['photos_checked'],
                                   'overlap_held':r['perception']['photo_pairs_held']},
                         'source_receipt':r['receipt_sha256']},ensure_ascii=False,allow_nan=False).replace('</','<\\/')
    page='''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MOTIF FIELD-018 — Chain Under Test</title>
<style>
:root{color-scheme:dark;font-family:system-ui,-apple-system,Segoe UI,sans-serif;--bg:#121b22;--card:#1d2a34;--line:#344a59;--muted:#b8c6cf;--accent:#ffcd78}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#f0f5f5}header{padding:24px 5vw;background:#102b2f;border-bottom:4px solid #5d9e93}h1{margin:8px 0;font-size:clamp(27px,4vw,43px)}h2{font-size:23px}p{line-height:1.55}small,.muted{color:var(--muted)}main{max-width:1400px;margin:auto;padding:22px 4vw 55px}.eyebrow{font-size:13px;letter-spacing:.15em;font-weight:800;color:var(--accent)}.layout{display:grid;grid-template-columns:minmax(0,1.07fr) minmax(0,.93fr);gap:20px}.layout>div,.step>div,.card{min-width:0}.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:18px}.callout{border-left:4px solid var(--accent);background:#273039;padding:13px 15px}.step{display:flex;align-items:center;gap:14px;border-bottom:1px solid var(--line);padding:12px 0}.step:last-child{border:0}.step small{display:block;margin-top:4px}.badge{display:inline-flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;padding:7px 10px;min-width:110px;border-radius:5px;text-align:center}.pass{background:#224f3d;color:#9ce6b9}.synthetic{background:#4e3a22;color:#ffcf87}.blocked{background:#572d33;color:#ffd1d6}.held{background:#343c46;color:#dae2e9}.figures{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.figures figure{margin:0;background:#141f27;padding:8px;border-radius:10px;border:1px solid var(--line)}figure img{width:100%;height:130px;object-fit:contain}figure.sketch{grid-column:span 3}figure.sketch img{height:auto;max-height:490px}figcaption{font-size:12px;color:var(--muted);padding-top:6px}button{padding:11px 15px;border:1px solid #85aaa5;border-radius:8px;background:#244341;color:#effaff;font-weight:bold;cursor:pointer}button[aria-pressed=true]{background:#a56b32}button:hover{filter:brightness(1.15)}.choice{display:flex;gap:10px;flex-wrap:wrap}.detail{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;background:#111b24;border-radius:9px;padding:14px;margin-top:13px}pre{white-space:pre-wrap;word-break:break-word;font-size:12px}.inputgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.inputgrid>div,.figures figure{min-width:0}input,select{width:100%;border-radius:7px;background:#101b22;border:1px solid #667c8a;padding:10px;color:#f2f2f2;font:inherit}label{font-size:12px;color:var(--muted)}.metrics{display:flex;flex-wrap:wrap;gap:12px}.metric{min-width:125px;flex:1;padding:13px;background:#101c25;border-radius:9px}.metric b{font-size:26px;color:#a3d8d1;display:block}.warning{color:#ffcd78;font-weight:750}.diagram{width:100%;height:auto;max-height:175px;border:1px solid var(--line);border-radius:8px;background:#102029}footer{color:#bbcfcb;font-size:12px;padding:22px 0}@media(max-width:850px){.layout{grid-template-columns:minmax(0,1fr)}.inputgrid{grid-template-columns:1fr}.figures{grid-template-columns:repeat(2,minmax(0,1fr))}figure.sketch{grid-column:span 2}}
</style></head><body><header><div class="eyebrow">THE STATIC COLLECTIVE · MOTIF RESEARCH</div><h1>FIELD-018 · The Chain Under Test</h1><p>Actual pixels on one lane. Controlled mechanics and revision on another. No hidden bridge between them.</p></header><main><section class="metrics"><div class="metric"><b>''' + str(r['perception']['ink_groups']) + '''</b>tentative ink groups</div><div class="metric"><b>''' + str(r['perception']['photos_checked']) + '''</b>original yard photographs</div><div class="metric"><b>''' + str(r['perception']['photo_pairs_held']) + '''</b>photo overlaps held</div><div class="metric"><b>0</b>real 3D model calls</div></section><div class="layout"><div><section class="card"><h2>01 · Actual-source investigation</h2><p>These are the only results truly derived from the original images. Dotted strokes are marks on paper, not measured fence lengths. Photos stay in their individual camera frames.</p><div class="figures">''' + thumbs + '''</div></section><section class="card"><h2>02 · User-ready clarification</h2><p>Rather than ask you to explain a drawing again, register one useful board correction as a structured event. This only saves a local claim; it does <b>not</b> certify geometry or rerun a vision model.</p><div class="inputgrid"><div><label>What are you correcting?<select id="editType"><option value="confirm_desired_mark">Confirm intended dashed mark</option><option value="measure_panel">Measure a panel's usable width</option><option value="trace_target">Trace an intended fence segment</option><option value="confirm_mobility">Confirm movable section</option><option value="report_issue">Flag a real hazard</option></select></label></div><div><label>Source reference / object id<input id="subject" placeholder="e.g. photo-07 / panel A" maxlength="110"></label></div><div><label>Value or brief correction<input id="value" placeholder="e.g. 4.2 ft, approximately" maxlength="180"></label></div><div><label>Evidence type<select id="evidence"><option value="USER_REPORT">User report</option><option value="USER_MEASURED">Measured, user-reported</option><option value="USER_ESTIMATE">Approximate estimate</option><option value="VISUAL_CORRECTION">Sketch correction</option></select></label></div></div><div class="choice" style="margin-top:14px"><button id="save">Append correction</button><button id="export">Export evidence updates</button></div><small id="editsCount">0 evidence edits saved in this page</small><div class="detail" id="eventResult">No corrections entered. Original image evidence remains unchanged.</div></section></div><div><section class="card"><h2>Integration gates</h2>''' + stages + '''<p class="callout"><b>The bottleneck is not search depth:</b> the real photos still lack independently established object semantics and common metric geometry. Running more synthetic search can't repair that missing evidence.</p></section><section class="card"><h2>03 · Controlled synthetic chain</h2><p><span class="warning">Not your actual property.</span> This separate lane really executes FIELD-017 → FIELD-016 → FIELD-015 on authored test materials. The alternative can change after a simulated width revision.</p><div class="choice"><button id="before" aria-pressed="true">Before width correction</button><button id="after" aria-pressed="false">After synthetic correction</button></div><h3 id="winner">--</h3><p id="verdict"></p><svg class="diagram" id="schematic" viewBox="0 0 600 175" aria-label="illustrative assembly schematic"></svg><div id="details" class="detail"></div></section><section class="card"><h2>Next honest experiment</h2><p>Execute a genuine local open-weights image interpreter on <i>previously unseen</i> labeled photographs. Then independently verify same-object correspondences, a known scale and object properties before attempting field-meaningful mechanics.</p><p>Two 3D model adapters exist; neither MapAnything nor Depth Anything 3 actually ran here.</p><p><b>Safety:</b> connected panels, chairs and trampoline frames remain unverified supports; 200-lb zip-tie advertising is not installed joint strength. No constructed fence or dog enclosure is certified.</p></section></div></div><footer>Offline HTML. No external fonts, trackers, APIs, scripts, or automatic image transmission. Private embedded images remain inside this file; do not publish or share it publicly.</footer>
<script type="application/json" id="chain-data">''' + payload + '''</script><script>
(()=>{'use strict';const model=JSON.parse(document.getElementById('chain-data').textContent);let mode='first';let events=[];
const q=s=>document.querySelector(s),txt=(sel,v)=>{q(sel).textContent=String(v)};
function diagram(pieces){const names=pieces||[];let x=30;let out='<rect x="0" y="135" width="600" height="6" fill="#6ca992"/><line x1="0" y1="143" x2="600" y2="143" stroke="#a1bdb8" stroke-dasharray="6,6" />';let palette=['#6e9fba','#c1a86d','#94a78e'];for(let i=0;i<names.length;i++){let w=128+(i%2)*35;out+=`<g><rect x="${x}" y="52" width="${w}" height="84" rx="3" fill="${palette[i%palette.length]}" fill-opacity=".3" stroke="${palette[i%palette.length]}" stroke-width="3"/><line x1="${x}" x2="${x+w}" y1="70" y2="123" stroke="#9bb5ba" stroke-dasharray="7,4"/><text x="${x+8}" y="42" fill="white" font-size="17">${names[i].replace(/[^a-zA-Z0-9_]/g,'')}</text></g>`;x+=w+11;}return out+'<text x="24" y="166" fill="#c4cfda" font-size="14">Illustrative assembly only — not measured site geometry</text>'}
function update(){const s=model[mode];const id=s.winner.route+' / '+s.winner.pieces.join(' + ');txt('#winner',id);txt('#verdict',s.winner_verdict+' · '+s.evaluated+' actual candidate assessments');q('#schematic').innerHTML=diagram(s.winner.pieces);txt('#details','Known model failures: '+JSON.stringify(s.winner_model_failures||[])+'\\nUnresolved: '+JSON.stringify(s.winner_unknowns||[])+'\\nNext direct input: '+JSON.stringify(s.next_question));q('#before').setAttribute('aria-pressed',mode==='first');q('#after').setAttribute('aria-pressed',mode==='second')}
q('#before').onclick=()=>{mode='first';update()};q('#after').onclick=()=>{mode='second';update()};
q('#save').onclick=()=>{let subject=q('#subject').value.trim(),value=q('#value').value.trim();if(!subject||!value){txt('#eventResult','Supply an object/source reference and a value before saving.');return}let obj={type:q('#editType').value,subject,value,source:q('#evidence').value,kind:'USER_SUBMITTED_BOARD_EVENT',verified_external_measurement:false,source_sha256:model.source_receipt,event_number:events.length+1};events.push(obj);txt('#editsCount',events.length+' local corrections');txt('#eventResult',JSON.stringify(obj,null,2));};
q('#export').onclick=()=>{const blob=new Blob([JSON.stringify({experiment:'FIELD-018',source_sha256:model.source_receipt,events},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='FIELD018_local_evidence_updates.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
update();})();
</script></main></body></html>'''
    Path(out_path).write_text(page,encoding='utf-8')
    return str(out_path)
